private val COUNTRY_BY_CODE: Map<String, CountryInfo> = COUNTRIES.associateBy { it.code }

fun currencyForCountry(code: String): String = COUNTRY_BY_CODE[code]?.currency ?: "USD"

fun isKnownCountry(code: String): Boolean = COUNTRY_BY_CODE.containsKey(code)

/** i18n key for a continent group's label in a country picker, e.g.
 * "deposer.region_europe" — shared by every country picker (deposer-annonce,
 * the app-wide country switcher) so the mapping lives in exactly one place. */
fun regionLabelKey(region: ContinentRegion): String = "deposer.region_${region.name.lowercase()}"

/** Groups the full country list into continents for pickers — Morocco
 * pinned first as the platform's home market, then continents in a fixed,
 * stable order (mirrors web's COUNTRY_REGIONS). */
val COUNTRY_REGIONS: List<Pair<ContinentRegion, List<String>>> = listOf(
    ContinentRegion.MOROCCO, ContinentRegion.AFRICA, ContinentRegion.EUROPE, ContinentRegion.ASIA,
    ContinentRegion.NORTH_AMERICA, ContinentRegion.SOUTH_AMERICA, ContinentRegion.OCEANIA
).map { region -> region to COUNTRIES.filter { it.region == region }.map { it.code } }

/** Flag emoji computed from the ISO alpha-2 code (regional indicator
 * symbols) — no per-country emoji table to maintain. Unlike the web app,
 * Android renders these natively via Noto Color Emoji with no known
 * rendering bug, so (unlike web's FlagIconComponent/bundled SVGs) a plain
 * computed emoji is the pragmatic, already-proven approach here (see
 * I18nRepository.SUPPORTED_LANGUAGES's language-flag emoji). */
fun countryFlag(code: String): String =
    code.uppercase().map { 0x1F1E6 - 'A'.code + it.code }.joinToString("") { String(Character.toChars(it)) }

